{
  "name": "@dunning/system",
  "version": "1.0.0",
  "description": "Automated billing reminder state machine for dunning workflows",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "test:watch": "vitest",
    "lint": "eslint src/"
  },
  "devDependencies": {
    "@types/node": "^20.11.0",
    "typescript": "^5.3.0",
    "vitest": "^2.0.0"
  },
  "files": [
    "dist"
  ]
}

import { DunningState, DunningConfig, DunningStatus } from './types.js';

const DEFAULT_TIMEOUTS: Record<DunningStatus, number> = {
  'ISSUED': 0,
  'DUE_SOON': -7,
  'OVERDUE': 3,
  'GRACE': 7,
  'REMINDER_1': 14,
  'REMINDER_2': 14,
  'FINAL_NOTICE': 7,
  'SUSPENDED': 30,
  'WRITTEN_OFF': 0,
  'PAID': 0,
  'PAUSED': 0,
  'CANCELLED': 0
};

/**
 * Creates a new dunning instance for an invoice.
 * 
 * @param dueDate - The invoice due date
 * @param config - Optional configuration for timeouts and holidays
 * @returns Initial dunning state with ISSUED status
 */
export function createInstance(
  dueDate: Date,
  config?: Partial<DunningConfig>
): DunningState {
  const mergedConfig: DunningConfig = {
    timeouts: {
      ...DEFAULT_TIMEOUTS,
      ...config?.timeouts
    },
    holidays: config?.holidays ?? []
  };

  return {
    status: 'ISSUED',
    dueDate,
    stateEnteredAt: new Date(),
    config: mergedConfig
  };
}

export * from './types.js';
export * from './createInstance.js';
export * from './process.js';

import { DunningState, DunningEvent, ProcessResult, DunningStatus, ActionDescriptor } from './types.js';
import { addBusinessDays, countBusinessDays } from './utils/businessDays.js';

const STATE_ORDER: DunningStatus[] = [
  'ISSUED',
  'DUE_SOON',
  'OVERDUE',
  'GRACE',
  'REMINDER_1',
  'REMINDER_2',
  'FINAL_NOTICE',
  'SUSPENDED',
  'WRITTEN_OFF'
];

const TERMINAL_STATES: DunningStatus[] = ['PAID', 'WRITTEN_OFF', 'CANCELLED'];

const PAUSABLE_STATES: DunningStatus[] = ['OVERDUE', 'GRACE', 'REMINDER_1', 'REMINDER_2', 'FINAL_NOTICE', 'SUSPENDED'];

function getNextState(currentStatus: DunningStatus): DunningStatus | null {
  const currentIndex = STATE_ORDER.indexOf(currentStatus);
  if (currentIndex === -1 || currentIndex >= STATE_ORDER.length - 1) {
    return null;
  }
  return STATE_ORDER[currentIndex + 1];
}

function getTransitionTimeout(status: DunningStatus, config: { timeouts?: Partial<Record<DunningStatus, number>> }): number {
  return config.timeouts?.[status] ?? 0;
}

function getTransitionActions(toStatus: DunningStatus): ActionDescriptor[] {
  const actions: ActionDescriptor[] = [];

  if (toStatus === 'DUE_SOON') {
    actions.push({ type: 'send_email', template: 'due_soon_reminder' });
  } else if (toStatus === 'REMINDER_1') {
    actions.push({ type: 'send_email', template: 'first_reminder' });
  } else if (toStatus === 'REMINDER_2') {
    actions.push({ type: 'send_email', template: 'second_reminder' });
  } else if (toStatus === 'FINAL_NOTICE') {
    actions.push({ type: 'send_email', template: 'final_warning' });
  } else if (toStatus === 'SUSPENDED') {
    actions.push({ type: 'suspend_service' });
    actions.push({ type: 'send_email', template: 'service_suspended' });
  } else if (toStatus === 'WRITTEN_OFF') {
    actions.push({ type: 'send_email', template: 'written_off_notice' });
  }

  return actions;
}

function shouldTransitionToNextState(state: DunningState, now: Date): boolean {
  const { status, dueDate, config, stateEnteredAt, pausedFrom, pausedElapsed } = state;

  const holidays = config.holidays ?? [];

  if (status === 'ISSUED') {
    const dueSoonTimeout = getTransitionTimeout('DUE_SOON', config);
    const targetDate = addBusinessDays(dueDate, dueSoonTimeout, holidays);
    return now.getTime() >= targetDate.getTime();
  }

  if (pausedFrom !== undefined && pausedElapsed !== undefined) {
    const currentTimeout = getTransitionTimeout(status, config);
    const elapsedWhenPaused = pausedElapsed;
    const additionalDays = countBusinessDays(stateEnteredAt, now, holidays);
    const totalElapsed = elapsedWhenPaused + additionalDays;
    return totalElapsed >= currentTimeout;
  }

  const currentTimeout = getTransitionTimeout(status, config);
  const elapsedDays = countBusinessDays(stateEnteredAt, now, holidays);
  return elapsedDays >= currentTimeout;
}

function handleTickEvent(state: DunningState, now: Date): ProcessResult {
  if (TERMINAL_STATES.includes(state.status) || state.status === 'PAUSED') {
    return { state, actions: [] };
  }

  if (shouldTransitionToNextState(state, now)) {
    const nextStatus = getNextState(state.status);
    if (nextStatus) {
      const actions = getTransitionActions(nextStatus);
      return {
        state: {
          ...state,
          status: nextStatus,
          stateEnteredAt: now
        },
        actions
      };
    }
  }

  return { state, actions: [] };
}

function handlePaymentReceived(state: DunningState): ProcessResult {
  if (TERMINAL_STATES.includes(state.status)) {
    return { state, actions: [] };
  }

  const actions: ActionDescriptor[] = [];
  if (state.status === 'SUSPENDED') {
    actions.push({ type: 'resume_service' });
  }

  return {
    state: {
      ...state,
      status: 'PAID',
      stateEnteredAt: new Date()
    },
    actions
  };
}

function handleInvoiceCancelled(state: DunningState): ProcessResult {
  if (TERMINAL_STATES.includes(state.status)) {
    return { state, actions: [] };
  }

  const actions: ActionDescriptor[] = [];
  if (state.status === 'SUSPENDED') {
    actions.push({ type: 'resume_service' });
  }

  return {
    state: {
      ...state,
      status: 'CANCELLED',
      stateEnteredAt: new Date()
    },
    actions
  };
}

function handleDunningPaused(state: DunningState): ProcessResult {
  if (!PAUSABLE_STATES.includes(state.status)) {
    return { state, actions: [] };
  }

  const now = new Date();
  const holidays = state.config.holidays ?? [];
  const elapsedDays = countBusinessDays(state.stateEnteredAt, now, holidays);

  return {
    state: {
      ...state,
      status: 'PAUSED',
      pausedFrom: state.status,
      pausedElapsed: elapsedDays,
      stateEnteredAt: now
    },
    actions: []
  };
}

function handleDunningResumed(state: DunningState): ProcessResult {
  if (state.status !== 'PAUSED' || !state.pausedFrom) {
    return { state, actions: [] };
  }

  const previousStatus = state.pausedFrom;
  const now = new Date();

  return {
    state: {
      ...state,
      status: previousStatus,
      pausedFrom: undefined,
      pausedElapsed: undefined,
      stateEnteredAt: now
    },
    actions: []
  };
}

function handleManualAdvance(state: DunningState): ProcessResult {
  if (TERMINAL_STATES.includes(state.status) || state.status === 'PAUSED') {
    return { state, actions: [] };
  }

  if (!STATE_ORDER.includes(state.status)) {
    return { state, actions: [] };
  }

  const nextStatus = getNextState(state.status);
  if (!nextStatus) {
    return { state, actions: [] };
  }

  const actions = getTransitionActions(nextStatus);

  return {
    state: {
      ...state,
      status: nextStatus,
      stateEnteredAt: new Date()
    },
    actions
  };
}

/**
 * Processes a dunning event and returns the new state and any resulting actions.
 * This is a pure function that does not modify the input state.
 * 
 * @param state - The current dunning state
 * @param event - The event to process
 * @param now - The current date/time for evaluating timeouts
 * @returns A new state and list of action descriptors
 */
export function process(
  state: DunningState,
  event: DunningEvent,
  now: Date
): ProcessResult {
  switch (event.type) {
    case 'tick':
      return handleTickEvent(state, now);
    case 'payment_received':
      return handlePaymentReceived(state);
    case 'invoice_cancelled':
      return handleInvoiceCancelled(state);
    case 'dunning_paused':
      return handleDunningPaused(state);
    case 'dunning_resumed':
      return handleDunningResumed(state);
    case 'manual_advance':
      return handleManualAdvance(state);
    default:
      return { state, actions: [] };
  }
}

export type DunningStatus =
  | "ISSUED" | "DUE_SOON" | "OVERDUE" | "GRACE"
  | "REMINDER_1" | "REMINDER_2" | "FINAL_NOTICE"
  | "SUSPENDED" | "WRITTEN_OFF" | "PAID" | "PAUSED" | "CANCELLED"

export type EventType =
  | "tick" | "payment_received" | "invoice_cancelled"
  | "dunning_paused" | "dunning_resumed" | "manual_advance"

export interface DunningEvent {
  type: EventType
}

export type ActionType = "send_email" | "suspend_service" | "resume_service"

export interface ActionDescriptor {
  type: ActionType
  template?: string
}

export interface DunningConfig {
  timeouts?: Partial<Record<DunningStatus, number>>
  holidays?: Date[]
}

export interface DunningState {
  status: DunningStatus
  dueDate: Date
  stateEnteredAt: Date
  config: DunningConfig
  pausedFrom?: DunningStatus
  pausedElapsed?: number
}

export interface ProcessResult {
  state: DunningState
  actions: ActionDescriptor[]
}

function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

function normalizeDate(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function datesEqual(a: Date, b: Date): boolean {
  return a.getTime() === b.getTime();
}

function isHoliday(date: Date, holidays: Date[]): boolean {
  const normalizedDate = normalizeDate(date);
  return holidays.some(h => datesEqual(normalizeDate(h), normalizedDate));
}

export function isBusinessDay(date: Date, holidays: Date[] = []): boolean {
  if (isWeekend(date)) {
    return false;
  }
  if (isHoliday(date, holidays)) {
    return false;
  }
  return true;
}

export function addBusinessDays(startDate: Date, businessDays: number, holidays: Date[] = []): Date {
  let currentDate = normalizeDate(startDate);

  if (businessDays === 0) {
    return currentDate;
  }

  // Move to first business day if starting from non-business day
  if (businessDays > 0 && !isBusinessDay(currentDate, holidays)) {
    while (!isBusinessDay(currentDate, holidays)) {
      currentDate = new Date(currentDate.getTime() + 24 * 60 * 60 * 1000);
    }
  } else if (businessDays < 0 && !isBusinessDay(currentDate, holidays)) {
    while (!isBusinessDay(currentDate, holidays)) {
      currentDate = new Date(currentDate.getTime() - 24 * 60 * 60 * 1000);
    }
  }

  let daysAdded = 0;
  let result = new Date(currentDate);

  if (businessDays > 0) {
    while (daysAdded < businessDays) {
      result = new Date(result.getTime() + 24 * 60 * 60 * 1000);
      if (isBusinessDay(result, holidays)) {
        daysAdded++;
      }
    }
  } else {
    // Negative - subtract business days
    while (daysAdded > businessDays) {
      result = new Date(result.getTime() - 24 * 60 * 60 * 1000);
      if (isBusinessDay(result, holidays)) {
        daysAdded--;
      }
    }
  }

  return result;
}

export function countBusinessDays(startDate: Date, endDate: Date, holidays: Date[] = []): number {
  const start = normalizeDate(startDate);
  const end = normalizeDate(endDate);

  if (start.getTime() === end.getTime()) {
    return 0;
  }

  const [earlier, later] = start.getTime() < end.getTime() ? [start, end] : [end, start];

  let count = 0;
  let current = new Date(earlier);

  // Move past non-business days at the start
  while (current.getTime() < later.getTime() && !isBusinessDay(current, holidays)) {
    current = new Date(current.getTime() + 24 * 60 * 60 * 1000);
  }

  while (current.getTime() < later.getTime()) {
    if (isBusinessDay(current, holidays)) {
      count++;
    }
    current = new Date(current.getTime() + 24 * 60 * 60 * 1000);
  }

  return count;
}

import { describe, it, expect } from 'vitest';
import { addBusinessDays, countBusinessDays, isBusinessDay } from '../src/utils/businessDays.js';

describe('businessDays', () => {
  describe('addBusinessDays', () => {
    it('should add 0 business days to return same date', () => {
      const friday = new Date('2026-01-09'); // Friday
      const result = addBusinessDays(friday, 0);
      expect(result.getTime()).toBe(friday.getTime());
    });

    it('should add 1 business day skipping weekend', () => {
      const friday = new Date('2026-01-09'); // Friday
      const result = addBusinessDays(friday, 1);
      // Should be Monday (Jan 12)
      expect(result.getDay()).toBe(1); // Monday
    });

    it('should add 3 business days skipping weekend', () => {
      const friday = new Date('2026-01-09'); // Friday
      const result = addBusinessDays(friday, 3);
      // Friday + 1 = Monday, + 2 = Tuesday, + 3 = Wednesday
      expect(result.getDay()).toBe(3); // Wednesday
    });

    it('should exclude holidays from business day count', () => {
      const monday = new Date('2026-01-12'); // Monday
      const holidays = [new Date('2026-01-13')]; // Tuesday is a holiday
      const result = addBusinessDays(monday, 1, holidays);
      // Monday + 1 = Tuesday (holiday, skipped) = Wednesday
      expect(result.getDay()).toBe(3); // Wednesday
    });

    it('should use default empty holidays array', () => {
      const friday = new Date('2026-01-09');
      const result = addBusinessDays(friday, 1);
      expect(result.getDay()).toBe(1); // Monday
    });
  });

  describe('countBusinessDays', () => {
    it('should count 0 business days for same day', () => {
      const monday = new Date('2026-01-12');
      const result = countBusinessDays(monday, monday);
      expect(result).toBe(0);
    });

    it('should count business days between Monday and Friday', () => {
      const monday = new Date('2026-01-12');
      const friday = new Date('2026-01-16');
      const result = countBusinessDays(monday, friday);
      expect(result).toBe(4); // Mon, Tue, Wed, Thu (not including Friday)
    });

    it('should count business days from Saturday to Monday as 0', () => {
      const saturday = new Date('2026-01-10');
      const monday = new Date('2026-01-12');
      const result = countBusinessDays(saturday, monday);
      expect(result).toBe(0); // Saturday is not a business day, skipped; Sunday excluded; Monday is end (exclusive)
    });

    it('should count 1 business day from Friday to Monday', () => {
      const friday = new Date('2026-01-09');
      const monday = new Date('2026-01-12');
      const result = countBusinessDays(friday, monday);
      expect(result).toBe(1); // Friday is a business day and is included
    });

    it('should exclude holidays', () => {
      const monday = new Date('2026-01-12');
      const wednesday = new Date('2026-01-14');
      const holidays = [new Date('2026-01-13')]; // Tuesday is holiday
      const result = countBusinessDays(monday, wednesday, holidays);
      expect(result).toBe(1); // Only Monday (Tuesday is holiday)
    });
  });

  describe('isBusinessDay', () => {
    it('should return true for Monday', () => {
      const monday = new Date('2026-01-12');
      expect(isBusinessDay(monday)).toBe(true);
    });

    it('should return false for Saturday', () => {
      const saturday = new Date('2026-01-10');
      expect(isBusinessDay(saturday)).toBe(false);
    });

    it('should return false for Sunday', () => {
      const sunday = new Date('2026-01-11');
      expect(isBusinessDay(sunday)).toBe(false);
    });

    it('should return false for holiday', () => {
      const tuesday = new Date('2026-01-13');
      const holidays = [new Date('2026-01-13')];
      expect(isBusinessDay(tuesday, holidays)).toBe(false);
    });

    it('should return true for non-holiday weekday', () => {
      const tuesday = new Date('2026-01-13');
      const holidays = [new Date('2026-01-14')]; // Wednesday is holiday
      expect(isBusinessDay(tuesday, holidays)).toBe(true);
    });
  });
});

import { describe, it, expect } from 'vitest';
