  }
  return true;
}

export function addBusinessDays(startDate: Date, businessDays: number, holidays: Date[] = []): Date {
  const currentDate = normalizeDate(startDate);

  if (businessDays === 0) {
    return currentDate;
  }

  // Find the first business day before/after start date to begin counting
  let start = new Date(currentDate);

  // Adjust to start from a business day if not already
  if (businessDays > 0 && !isBusinessDay(start, holidays)) {
